local config = {
  ui_story_30860401_1_dialog_content = "Então, está dizendo que achou algumas <color=#FFB400>flores brancas</color> na Colossus?",
  ui_story_30860401_2_dialog_content = "A sua flor branca, precisamente.",
  ui_story_30860401_3_dialog_content = "Eu tenho acordado cedo para treinar nesses últimos dias...",
  ui_story_30860401_4_dialog_content = "E comecei a notar esse cheiro estranho de flor.",
  ui_story_30860401_5_dialog_content = "Finalmente, essa manhã mesmo, achei de onde vinha o cheiro.",
  ui_story_30860401_6_dialog_content = "Alguém colocou essas flores brancas misteriosas em todos os cantos da Colossus...",
