  ui_story_30860401_21_dialog_content = "Baixam a cabeça em <color=#FFB400>oração</color>.",
  ui_story_30860401_22_dialog_content = "E expressam suas <color=#FFB400>condolências</color>!",
  ui_story_30860401_23_dialog_content = "(Prece? Condolência? Por que soa como um <color=#FFB400>agente funerário</color>?!)",
  ui_story_30860401_24_dialog_content = "É <color=#FFB400>Uriah</color>!",
  ui_story_30860401_25_dialog_content = "Você não me engana!",
