  ui_story_30860401_30_option_content = "Você não está sendo acusado de um crime, nem nada...",
  ui_story_30860401_31_dialog_content = "Estava curioso, só isso.",
  ui_story_30860401_32_dialog_content = "Todas essas flores cobrindo a Colossus...",
