  ui_story_30860401_34_dialog_content = "Já que você tem tanta certeza de que fui eu, me desculpe.",
  ui_story_30860401_35_dialog_content = "Mesmo que isto realmente não seja algo que precise ser mantido escondido.",
  ui_story_30860401_36_dialog_content = "Então foi você que colocou essas flores?",
  ui_story_30860401_37_dialog_content = "É só uma pequena parte das minhas preces. Espero que você não se ofenda.",
  ui_story_30860401_38_option_content = "Eu não ligo, claro...",
  ui_story_30860401_39_dialog_content = "Quando muito, me anima ver tantas flores depois de treinar o dia inteiro.",
  ui_story_30860401_40_option_content = "Só me preocupa se isso machucará o Soroz...",
  ui_story_30860401_41_dialog_content = "Por favor, fique tranquilo, essas flores não crescem naturalmente – até os seus caules são feitos da minha vinha florida.",
  ui_story_30860401_42_dialog_content = "Eu as espalhei pela Colossus como sinal do meu respeito.",
  ui_story_30860401_43_dialog_content = "Agora que você mencionou, as suas vinhas floridas têm essas flores brancas também. São as suas favoritas?",
