  ui_story_30860401_49_dialog_content = "Então o seu poder está ligado ao significado delas?",
  ui_story_30860401_50_dialog_content = "Essa flor simboliza “<color=#FFB400>um trágico adeus</color>”.",
  ui_story_30860401_51_dialog_content = "Então... seu poder está ligado ao adeus?",
  ui_story_30860401_52_dialog_content = "Está relacionado à sua família?",
  ui_story_30860401_53_dialog_content = "Sim... e a mim também.",
  ui_story_30860401_54_dialog_content = "Você tem sido tão gentil, me ouvindo por todo esse tempo. Vou rezar por você dia e noite.",
  ui_story_30860401_55_dialog_content = "Às vezes, não sei se você está falando sério ou não.",
  ui_story_30860401_56_dialog_content = "Huhum, enfim... Como Navegador, é minha função entender minha tripulação o máximo possível, concorda?",
  ui_story_30860401_57_dialog_content = "Se você realmente quer saber, eu ficaria muito feliz em falar sobre o meu passado.",
  ui_story_30860401_58_dialog_content = "Mas em troca, você vai me contar sobre as coisas pelas quais você lamenta?",
  ui_story_30860401_59_dialog_content = "Eu? O que isso tem a ver comigo?",
  ui_story_30860401_60_dialog_content = "Sua família, por exemplo. As coisas que você quer proteger... As coisas que você teve que deixar para trás...",
  ui_story_30860401_61_dialog_content = "Isso tudo é passado... Além do mais, eu não lembro muito da minha família.",
  ui_story_30860401_62_dialog_content = "Qualquer coisa. Por favor?",
  ui_story_30860401_63_dialog_content = "Humm... Bem, tenho certeza que você já ouviu que eu fui criado pelo Soroz, certo?",
  ui_story_30860401_64_dialog_content = "Ah, sim, a incrível Colossus Branca.",
  ui_story_30860401_65_dialog_content = "Por 17 anos, eu cresci aqui. No começo, eu não entendia nada do mundo lá fora.",
  ui_story_30860401_66_dialog_content = "Todas as imagens na minha mente eram fragmentos de memórias que recebi de Soroz...",
  ui_story_30860401_67_dialog_content = "Como eu estava escondido nessa Colossus...",
  ui_story_30860401_68_dialog_content = "E como o meu povo morreu lutando contra Eclipsitas... para me proteger.",
  ui_story_30860401_69_dialog_content = "Mas, de novo, essas memórias foram plantadas em meu cérebro. Não tenho como confirmar se elas são reais ou não...",
  ui_story_30860401_70_dialog_content = "Eu também soube disso.",
  ui_story_30860401_71_dialog_content = "E também de algo que você não sabe.",
  ui_story_30860401_72_dialog_content = "Algo... que eu não sei?",
  ui_story_30860401_73_dialog_content = "Lembra-se da <color=#FFB400>marca vermelha na asa da Colossus</color>?",
  ui_story_30860401_74_option_content = "Sim, eu lembro...",
  ui_story_30860401_75_dialog_content = "Certa vez quando eu limpava a Colossus, Vice brigou comigo porque Soroz estava muito acabado. Isso a deixou bem chateada por algum tempo.",
  ui_story_30860401_76_option_content = "Não me lembro...",
  ui_story_30860401_77_dialog_content = "Mas há muito tempo, tinha essa marca na Colossus que eu não conseguia limpar, por mais que eu tentasse.",
  ui_story_30860401_78_dialog_content = "Aquelas marcas contam uma história. Não é só sujeira em uma máquina.",
  ui_story_30860401_79_dialog_content = "O que era então?",
  ui_story_30860401_80_dialog_content = "Em todas aquelas memórias fragmentadas... tem certeza que você não viu isso antes?",
  ui_story_30860401_81_dialog_content = "Espera, será que é...",
  ui_story_30860401_82_dialog_content = "Exato. Não era uma mancha qualquer, mas o <color=#FFB400>sangue</color> de seu companheiro Celestita.",
  ui_story_30860401_83_dialog_content = "Soroz nunca os esqueceu. É um símbolo de sua história enquanto você crescia.",
  ui_story_30860401_84_dialog_content = "Como você descobriu isso, Uriah?",
  ui_story_30860401_85_dialog_content = "Quando eu cheguei na Colossus, eu me deparei com esse <color=#FFB400>diário</color>...",
  ui_story_30860401_86_dialog_content = "Ele talvez seja de uma pessoa que não está mais conosco... As páginas estão repletas de histórias sobre você e o seu povo.",
  ui_story_30860401_87_dialog_content = "Por favor, me desculpe, eu não deveria ter lido.",
  ui_story_30860401_88_dialog_content = "Eu não tinha ideia quando o encontrei e estive esperando pela chance de entregar a você.",
  ui_story_30860401_89_dialog_content = "Eu rezei por esse momento por tanto tempo...",
  ui_story_30860401_90_dialog_content = "E agora, acredito que seja a hora certa de lhe devolver.",
  ui_story_30860401_91_dialog_content = "Esse diário e essas flores... Por favor os aceite.",
  ui_story_30860401_92_dialog_content = "Espero que possa lamentar e rezar pelos que se foram, e se despedir deles adequadamente.",
  ui_story_30860401_93_dialog_content = "*Pega flores alvas*",
  ui_story_30860401_94_dialog_content = "Segundo aquele diário, hoje é o dia de lamentar os que se foram...",
  ui_story_30860401_95_dialog_content = "Uma despedida adequada, hum... É a primeira vez que ouço falar de um feriado assim.",
  ui_story_30860401_96_dialog_content = "Eu deveria fazer algo especial em memória deles... Obrigado.",
  ui_story_30860401_97_dialog_content = "Assim como todos, eu também rezo por você.",
  ui_story_30860401_98_dialog_content = "Diga... Por que parece que eu estou esquecendo de algo?",
  ui_story_30860401_99_dialog_content = "Está?",
  ui_story_30860401_100_dialog_content = "Não... estou?",
  ui_story_30860401_101_dialog_content = "Acho que não. Você deveria descansar um pouco. Eu vou rezar por você hoje à noite, antes de dormir.",
  ui_story_30860401_X101_dialog_content = "Até a próxima.",
  ui_story_30860401_102_dialog_content = "Espere, agora eu me lembro! Você deveria me contar sobre o seu passado...",
  ui_story_30860401_103_dialog_content = "Aonde ela foi?",
  ui_story_30860401_104_dialog_content = "Uriah!!",
  ui_story_30860601_1_dialog_content = "Consegue ouvir esses <color=#FFB400>sons</color>?",
  ui_story_30860601_2_dialog_content = "Sons?",
  ui_story_30860601_3_dialog_content = "As ondas quebrando na praia, gaivotas grasnando enquanto brincam.",
  ui_story_30860601_4_dialog_content = "As folhas largas das palmeiras balançando ao vento, o som de passos na areia.",
  ui_story_30860601_5_dialog_content = "Todos esses sons estão transbordando com a energia do verão! Ah, é tão reconfortante...",
  ui_story_30860601_6_dialog_content = "Ouça com atenção.",
  ui_story_30860601_7_dialog_content = "Nossa, você tem razão! Quando presto atenção, consigo ouvir muitos sons ao nosso redor!",
  ui_story_30860601_8_dialog_content = "Sim.",
  ui_story_30860601_9_dialog_content = "(Não é sempre que Uriah tem essa expressão no rosto.)",
  ui_story_30860601_10_dialog_content = "(Normalmente ela é solene e elegante, vestida dos pés à cabeça... quase como uma escultura.)",
  ui_story_30860601_11_dialog_content = "(Mas parece que nem mesmo seu jeito sério é capaz de resistir à praia.)",
  ui_story_30860601_12_dialog_content = "Sei o que está pensando. Que você raramente me vê assim.",
  ui_story_30860601_13_dialog_content = "Mas essas roupas são perfeitas para o calor do verão.",
  ui_story_30860601_14_dialog_content = "Acha que fico bem nelas?",
  ui_story_30860601_15_option_content = "Com certeza!",
  ui_story_30860601_16_dialog_content = "Mesmo tendo sido desenhadas para a água, elas ainda carregam a qualidade e o estilo elegante de Lumópolis.",
  ui_story_30860601_17_dialog_content = "Ao vesti-las, todos ficam com um ar gracioso e devoto! Como uma pérola no oceano!",
  ui_story_30860601_18_dialog_content = "Eu... não sei se estou falando coisa com coisa.",
  ui_story_30860601_19_dialog_content = "Nunca pensei que receberia um elogio tão sincero de você. Agradeço imensamente.",
  ui_story_30860601_20_dialog_content = "Pra falar a verdade, achei que você ainda ia usar seu traje de freira quando chegou na praia.",
  ui_story_30860601_21_option_content = "É um pouco inesperado.",
  ui_story_30860601_22_dialog_content = "Essas roupas são realmente diferentes do que costumo vestir.",
  ui_story_30860601_23_dialog_content = "Em minha mente, você está sempre com o traje de freira.",
  ui_story_30860601_24_dialog_content = "Devo me vestir solenemente às orações.",
  ui_story_30860601_25_dialog_content = "Eu cuido meticulosamente das minhas roupas, assim como das minhas flores brancas.",
  ui_story_30860601_26_dialog_content = "Isso é um sinal de respeito aos feridos, os finados e os entes queridos que eles deixaram para trás.",
  ui_story_30860601_27_dialog_content = "Acredito que ninguém gostaria de ver a pessoa que vai guiá-los por momentos difíceis vestida informalmente. Não é mesmo?",
  ui_story_30860601_28_dialog_content = "Contudo, estou de folga no momento.",
  ui_story_30860601_29_dialog_content = "Por que decidiu vir para o Monarca do Oceano?",
  ui_story_30860601_30_dialog_content = "Eu vim a pedido de Lady Carleen.",
  ui_story_30860601_31_dialog_content = "Ela é uma moça gentil e atenciosa. Acha que eu trabalho demais e deseja que eu dedique mais tempo para mim mesma.",
  ui_story_30860601_32_dialog_content = "Eu não poderia recusar um convite tão gracioso e amável como esse.",
  ui_story_30860601_33_dialog_content = "Além disso... ouvi falar do Monarca do Oceano há muito tempo e sempre quis visitá-lo pessoalmente.",
  ui_story_30860601_34_dialog_content = "Talvez eu até descubra <color=#FFB400>o som pelo qual venho procurando</color>.",
  ui_story_30860601_35_dialog_content = "Você conhece o Monarca do Oceano, PlayerName?",
  ui_story_30860601_36_dialog_content = "Bonacie me contou. O Monarca do Oceano é uma cerimônia deixada pelos Aurorians que viviam nesta praia.",
  ui_story_30860601_37_dialog_content = "É uma competição que põe à prova a <color=#FFB400>força</color>, <color=#FFB400>sabedoria</color> e <color=#FFB400>bravura</color> dos participantes para determinar um vencedor.",
  ui_story_30860601_38_dialog_content = "Acredita-se que o festival abençoa esse lugar com um clima favorável.",
  ui_story_30860601_39_dialog_content = "Você tem toda a razão, mas sabe por que o Monarca do Oceano testa essa três qualidades?",
  ui_story_30860601_40_dialog_content = "Há uma história por trás disso?",
  ui_story_30860601_41_dialog_content = "\"Os sons carregam histórias do passado.\"",
  ui_story_30860601_42_dialog_content = "Há muito tempo, as pessoas desta costa dependiam das dádivas do céu e do mar para sobreviver.",
  ui_story_30860601_43_dialog_content = "Com o tempo, eles deixaram de dar valor ao que recebiam.",
  ui_story_30860601_44_dialog_content = "Então, um dia, a chuva desapareceu dos céus, o mar recuou e tudo o que vivia nas águas morreu.",
  ui_story_30860601_45_dialog_content = "Ao longe, um imponente castelo se ergueu das profundezas do mar e nuvens escuras cobriram toda a Costa Celestial.",
  ui_story_30860601_46_dialog_content = "Apenas quando as provações das deusas da Força, da Sabedoria e da Bravura fossem concluídas, a costa voltaria ao normal.",
  ui_story_30860601_47_dialog_content = "É nessa hora que um herói aparece pra salvar o dia!",
  ui_story_30860601_48_dialog_content = "Exatamente.",
  ui_story_30860601_49_dialog_content = "Para salvar a praia, um <color=#FFB400>rei</color> da época deu um passo firme à frente.",
  ui_story_30860601_50_dialog_content = "Usando sua força inabalável, ele escalou o castelo.",
  ui_story_30860601_51_dialog_content = "Com sua mente afiada, ele derrotou a Deusa da Sabedoria em seu próprio jogo.",
  ui_story_30860601_52_dialog_content = "Finalmente, com sua nobre coragem, ele superou seus piores medos e passou no teste da Deusa da Bravura.",
  ui_story_30860601_53_dialog_content = "No fim, o rei caiu nas graças das três deusas.",
  ui_story_30860601_54_dialog_content = "Após sua bênção, a chuva começou a cair novamente e o mar avançou até a praia, trazendo vida com ele.",
  ui_story_30860601_55_dialog_content = "As deusas, com seu poder, mandaram o rei de volta ao seu próprio reino.",
  ui_story_30860601_56_dialog_content = "Contudo, o mundo está em constante mudança, e já não era mais o mesmo do seu reinado.",
  ui_story_30860601_57_dialog_content = "Cem anos se passaram, e seus familiares e amigos há muito haviam deixado o mundo.",
  ui_story_30860601_58_dialog_content = "Tomado pela dor, o rei transformou-se em pedra no topo de um penhasco, de onde poderá para sempre proteger o futuro do seu reino.",
  ui_story_30860601_59_dialog_content = "Ainda que seus entes queridos não estejam mais com ele, a história de suas façanhas sobreviveram ao teste do tempo. O Monarca do Oceano foi então criado para honrar o rei e as três deusas.",
  ui_story_30860601_60_dialog_content = "Para os locais, força, sabedoria e bravura são as qualidades mais admiráveis em uma pessoa.",
  ui_story_30860601_61_dialog_content = "Parece um conto de fadas.",
  ui_story_30860601_62_dialog_content = "Está insinuando que a história não é real?",
  ui_story_30860601_X62_dialog_content = "Talvez um pouco...",
  ui_story_30860601_63_dialog_content = "Mesmo que a história pareça inventada, o Monarca do Oceano é bem real.",
  ui_story_30860601_64_dialog_content = "Assim como as provações de força, sabedoria e bravura.",
  ui_story_30860601_65_dialog_content = "(Mesmo que essas \"provações\" sejam apenas voleibol, xadrez e caraoquê...)",
  ui_story_30860601_66_dialog_content = "O que você acha da história, Uriah?",
  ui_story_30860601_67_dialog_content = "O que eu acho? Bem...",
  ui_story_30860601_68_dialog_content = "Vamos, não há nada de especial aqui.",
  ui_story_30860601_69_dialog_content = "O que é aquele tumulto ali?",
  ui_story_30860601_70_dialog_content = "Eu já disse, esse tipo de evento só serve pra tirar o dinheiro dos turistas.",
  ui_story_30860601_71_dialog_content = "Eles fazem o maior auê, depois organizam um monte de eventos sem sentido para movimentar os negócios.",
  ui_story_30860601_72_dialog_content = "Após isso, eles montam barracas por toda parte pra saírem no lucro. Raspa-raspa, bebidas geladas, trajes de banho, itens de praia...",
  ui_story_30860601_73_dialog_content = "No fim, o objetivo de tudo isso é fazer a gente puxar a carteira e desembolsar alguma grana.",
  ui_story_30860601_74_dialog_content = "Quer dizer, ninguém acredita mesmo nessa baboseira de \"Monarca do Oceano\", né? Ou nessas bobagens sobre força, bravura e sabedoria...",
  ui_story_30860601_75_dialog_content = "(Preciso admitir que ele tem certa razão...)",
  ui_story_30860601_76_dialog_content = "Já chega.",
  ui_story_30860601_77_dialog_content = "...",
  ui_story_30860601_78_dialog_content = "Tudo bem, Uriah?",
  ui_story_30860601_79_dialog_content = "Sim. O que ele disse está correto.",
  ui_story_30860601_80_dialog_content = "Independentemente de nossas opiniões ou ideias, lendas assim estão fadadas a desaparecer, deixando apenas um vislumbre do que um dia significaram.",
  ui_story_30860601_81_dialog_content = "O Monarca do Oceano, o rei de pedra, o castelo no mar... tudo isso existe na imaginação das pessoas, e se transformará até desaparecer por completo.",
  ui_story_30860601_82_dialog_content = "Que pena... Esse definitivamente não é o som que eu esperava ouvir.",
  ui_story_30860601_83_dialog_content = "Uriah!",
  ui_story_30860601_84_dialog_content = "Sim?",
  ui_story_30860601_85_dialog_content = "Eu.. eu quero acreditar na história!",
  ui_story_30860601_86_dialog_content = "PlayerName?",
  ui_story_30860601_87_dialog_content = "Porque... <size=45>eu acho ela bem romântica!</size>",
  ui_story_30860601_88_dialog_content = "Para proteger seu lar, o rei enfrentou muitos desafios... Ele provou que sua força, bravura e sabedoria eram reais!",
  ui_story_30860601_89_dialog_content = "E mesmo após as provações mudarem sua vida, ele nunca se arrependeu, e até mesmo transformou-se em pedra para continuar protegendo sua costa...",
  ui_story_30860601_90_dialog_content = "Se o Monarca do Oceano surgiu de um conto assim, então ele DEVE ter um significado!",
  ui_story_30860601_91_dialog_content = "Hmm... Então é assim que se sente, PlayerName.",
  ui_story_30860601_92_dialog_content = "(Parece que Uriah está pensativa. Será que eu disse algo errado?)",
  ui_story_30860601_93_dialog_content = "Não fique nervoso, PlayerName. O som da sua voz enquanto expressa suas ideias é poderoso e convincente.",
  ui_story_30860601_94_dialog_content = "Além disso, acho sua interpretação da história bem interessante. Esse é o tipo de som que gosto de ouvir.",
  ui_story_30860601_95_dialog_content = "Você sabia que as conchas também preservam os sons?",
  ui_story_30860601_96_dialog_content = "Uma concha guarda lindos ecos do passado em sua espiral. Quando fazemos uma pergunta, ela responde imediatamente.",
  ui_story_30860601_97_dialog_content = "Quero preservar sua voz. Então, por favor... repita as palavras que você me disse dentro desta concha!",
  ui_story_30860601_98_dialog_content = "Dentro da concha?",
  ui_story_30860601_99_dialog_content = "(Por que estão todos olhando?! Isso ficou estranho de repente...)",
  ui_story_30860601_100_dialog_content = "(Mas, se for pela Uriah... eu faço!)",
  ui_story_30860601_101_dialog_content = "<size=45>Acho que a história do Monarca do Oceano é muito romântica!</size>",
  ui_story_30860601_102_dialog_content = "Hmm, não pensei que havia pessoas tão ingênuas assim no mundo.",
  ui_story_30860601_103_dialog_content = "Vamos embora...",
  ui_story_30860601_104_dialog_content = "Sim, claro...",
  ui_story_30860601_105_dialog_content = "(Mas também acho a história do Monarca do Oceano muito romântica...)",
  ui_story_30860601_106_dialog_content = "Obrigada, PlayerName.",
  ui_story_30860601_107_dialog_content = "Também foi uma surpresa conhecer esse seu lado. Uma boa surpresa.",
  ui_story_30860601_108_dialog_content = "Honestamente, sei que essas histórias não são exatamente reais.",
  ui_story_30860601_109_dialog_content = "Mas eu vejo dor e sofrimento reais quase todos os dias, então aprendi a valorizar as pequenas alegrias que contos assim podem proporcionar.",
  ui_story_30860601_110_dialog_content = "Bem, se você está feliz, também estou!",
  ui_story_30860601_111_dialog_content = "Como poderia ser infeliz com você aqui?",
  ui_story_30860601_112_dialog_content = "O verdadeiro significado dos feriados e festivais está no que é passado pelas gerações.",
  ui_story_30860601_113_dialog_content = "Para nós, o valor está <color=#FFB400>naquilo que acreditamos</color>.",
  ui_story_30860601_114_dialog_content = "Eu já tenho fé em algo que vale a pena.",
  ui_story_30860601_115_dialog_content = "E esse \"algo\" é a nossa escolha em acreditar naquelas <color=#FFB400>qualidades honestas e benignas</color>.",
  ui_story_30860601_116_dialog_content = "Força, sabedoria e bravura.",
  ui_story_30860601_117_dialog_content = "Por fim, acredito que um pouco de romantismo pode levar a uma vida mais duradoura e feliz.",
  ui_story_30860601_118_dialog_content = "Também acredito que alguém como você terá uma vida cheia de alegria, independentemente de suas dificuldades.",
  ui_story_30860601_119_dialog_content = "Vamos encerrar nossa caminhada por aqui. Precisamos voltar e descansar.",
  ui_story_30860601_120_dialog_content = "Claro. Vamos pegar o caminho de volta.",
  ui_story_30860601_121_dialog_content = "Ah, e mais uma coisa.",
  ui_story_30860601_122_dialog_content = "<color=#e8d9bb>Uriah pega a concha e sussurra algo em seu interior.</color>",
  ui_story_30860601_123_dialog_content = "Uriah?",
  ui_story_30860601_124_dialog_content = "Estava apenas preservando o que eu mais queria dizer agora.",
  ui_story_30860601_125_dialog_content = "Mas é um segredo. Talvez um dia você seja capaz de ouvi-lo dentro dessa concha.",
  ui_story_30860601_126_dialog_content = "\"Obrigada, PlayerName. Esse é o som que eu mais queria ouvir hoje.\""
}
return config
